-- Vizta Learning — turn on graded, auto-scored practice (20 pts each).
-- Paste into the Supabase SQL editor and Run. Safe to re-run.

alter table public.submissions add column if not exists practice text;
alter table public.submissions add column if not exists practice_score integer;

-- Refresh lesson content (practice sections are now graded)
update public.activities set sections = '[{"type": "read", "title": "Warm up: what your eyes already do", "minutes": 10, "body": "You already read film language every day without noticing. When a video makes you feel tense, excited, or sad, a filmmaker put that feeling there on purpose. It was a choice, not an accident.\n\nTake five minutes. Think of one scene from any film or show that stuck with you. Do not worry yet about why. Hold it in your mind. By the end of this task you will take it apart like a maker, not just a viewer."}, {"type": "read", "title": "The grammar of shots: a closer look", "minutes": 28, "body": "Film has a grammar. Shots are the words, cuts are the punctuation, and angles and movement are the tone of voice.\n\nSHOT SIZES. A wide (or establishing) shot shows a whole place, so we know where we are. A medium shot shows a person from the waist up, good for conversation. A close-up fills the frame with a face or a detail, so we feel emotion. An extreme close-up pushes to an eye or a shaking hand, for maximum tension.\n\nANGLES. Eye-level feels natural. A high angle looks down and makes a subject feel small or vulnerable. A low angle looks up and makes them feel powerful. A tilted (Dutch) angle makes a moment feel wrong.\n\nMOVEMENT. A still camera feels calm. A pan or tilt follows action. A dolly or tracking shot glides and feels cinematic. A handheld camera shakes slightly and feels raw and real.\n\nCUTS. A cut is the join between two shots. Most are invisible on purpose. A cut on action hides the edit inside a movement. Cross-cutting jumps between two places to build suspense.\n\nYou do not need to memorize these like a test. You need to recognize them, because once you can name a choice, you can make it on purpose."}, {"type": "read", "title": "Worked example: how to read one scene", "minutes": 20, "body": "Here is the method in action, so you can copy the shape of the thinking. This is a model, not a film you must watch.\n\nImagine a chase down a narrow alley. Watch three choices work together:\n\nFIRST, the cuts get shorter and shorter, until each lasts less than a second. CHOICE: fast cutting. EFFECT: your heartbeat climbs.\n\nSECOND, the camera is handheld, right behind the runner. We are inside the fear, not watching calmly. CHOICE: handheld. EFFECT: we feel unsafe too.\n\nTHIRD, at the dead end the camera drops to a low angle looking up at the wall, so it towers over us. CHOICE: low angle. EFFECT: the obstacle feels impossible.\n\nNotice the shape: name the choice, then name the feeling. Never just say ''it was exciting.'' Say WHAT the filmmaker did and WHAT it did to you. That is a critique."}, {"type": "do", "title": "Guided practice: the freeze-frame hunt", "minutes": 30, "body": "Try it before the graded activity. Open any film or show you can watch legally at home.\n\n1. Pause on three different frames that catch your eye.\n2. For each, write the shot size (wide, medium, close-up, extreme), the angle (eye-level, high, low), and whether the camera was still or moving.\n3. In one sentence per frame, say what that choice made you feel.\n\nIt warms up the exact muscle you use below.\n\nWrite up your practice in the box below and submit it. It is auto-graded out of 20 on completion: 10 points for doing it, 10 for enough detail."}, {"type": "reflect", "title": "Reflection before your activity", "minutes": 10, "body": "Answer these for yourself before you write your activity. You do not submit them.\n\n- Which tool (shot size, angle, movement, or cuts) do you now notice most easily?\n- Which one is still hard to spot?\n- In the scene you thought about at the start, can you name one craft choice and the feeling it created?"}]'::jsonb where activity_id = 'G9-A1.1';
update public.activities set sections = '[{"type": "read", "title": "Warm up: the 30-second guess", "minutes": 10, "body": "Think of the last time you knew a film''s genre within thirty seconds, before anything happened in the plot. How did you know? Your eyes and ears read the signals for you. Today you make that skill conscious."}, {"type": "read", "title": "How genre speaks before the story does", "minutes": 26, "body": "Genre is a promise the audience already understands. A film keeps or breaks that promise, but first it has to make it, and it makes it through look and sound long before the story explains anything.\n\nCOLOR tells you mood. Warm golds and soft light promise romance or comedy. Cold blues and heavy shadow promise horror, crime, or thriller.\n\nMUSIC AND SOUND set the pulse. Bouncy, bright music promises fun. Low drones and silence-then-shock promise fear. A swelling orchestra promises adventure or epic.\n\nPACE tells you the kind of ride. Fast cutting and quick scenes promise action or comedy. Slow, held shots promise drama or art film.\n\nSETTING AND COSTUME place the world: neon city, dusty barrio, spaceship, school hallway.\n\nCommon genres and their promises: horror (dread, threat), comedy (a light tone and a happy release), romance (two people, a love to win), action (spectacle and stakes), drama (real feeling and change), documentary (this is true).\n\nWhy this matters: once you can name the signals, they become tools. A filmmaker who knows the rules can honor them, play with them, or break them on purpose."}, {"type": "read", "title": "Worked example: reading the first minute", "minutes": 20, "body": "A model, not a film to watch. Imagine the opening minute of a film with no dialogue yet.\n\nThe screen is dim and blue. A single light flickers. The music is a low hum with one high, thin note. The camera holds still for a long time, then a door creaks and we cut fast to a close-up of a wide eye.\n\nRead the signals: cold color (dread), low drone plus a sudden sharp sound (fear), long stillness broken by a fast cut (a scare). Verdict before a word is spoken: this is horror.\n\nNotice the method. You did not use the plot. You named the look and sound signals, then named the promise. That is reading genre like a filmmaker."}, {"type": "do", "title": "Guided practice: signal spotting", "minutes": 30, "body": "Open the first two minutes of any film or trailer you can watch legally. With the sound ON:\n\n1. List four signals you notice: one about color, one about music/sound, one about pace, one about setting or costume.\n2. From those four signals alone, name the genre you expect.\n3. Then keep watching for one more minute. Were you right? If the film surprised you, what signal was misleading on purpose?\n\nThis trains the eye you will use in the activity.\n\nWrite up your practice in the box below and submit it. It is auto-graded out of 20 on completion: 10 points for doing it, 10 for enough detail."}, {"type": "reflect", "title": "Reflection before your activity", "minutes": 10, "body": "- Which signal do you rely on most: color, sound, pace, or setting?\n- Name one film that promised one genre and then broke that promise. What did breaking it make you feel?\n- Which genre would you most want to make, and what is its main promise to the audience?"}]'::jsonb where activity_id = 'G9-A1.2';
update public.activities set sections = '[{"type": "read", "title": "Warm up: a technique you admired", "minutes": 10, "body": "Think of one Filipino film, short, or teleserye moment that stayed with you. Not the whole story, just one moment that was built well. Today you learn to see how such a moment is made, and to steal the technique for your own work."}, {"type": "read", "title": "Big craft on a small budget", "minutes": 26, "body": "Filipino filmmakers have made powerful work with very little money for decades. That is a treasure chest for you, because limits force clever choices, and clever choices are exactly what you can copy.\n\nNATURAL LIGHT. A single window, a doorway, or a bare bulb can light a whole scene for free, and it often looks more honest than expensive equipment. Watch where the light comes from and what it hides.\n\nREAL LOCATIONS. A real house, a real market, a real jeepney gives a scene a truth a built set cannot fake, at almost no cost. The place becomes a character.\n\nTHE HUMAN FACE. When you cannot afford spectacle, you point the camera at a face and hold. A close-up on a real expression is the cheapest and strongest shot there is.\n\nSOUND AND SILENCE. Everyday sound, or the sudden absence of it, sets mood without a music budget.\n\nTHE LONG TAKE. Holding one shot without cutting makes a moment feel real and continuous, and it costs nothing but courage.\n\nThe lesson is not to memorize titles. It is to watch one work closely, see how one moment was built, and carry that one technique into your own films."}, {"type": "read", "title": "Worked example: the one-window scene", "minutes": 20, "body": "A model of how to study a technique. Imagine a quiet scene shot in a small room with only the light from one window.\n\nWhat the filmmaker did: they placed the actor so the window light falls on half the face and leaves the other half in shadow. No lamps, no crew, just the window. The split of light and dark makes the character look caught between two feelings.\n\nHow you would copy it: at home, near a window in the afternoon, sit so the light hits one side of your face. Film on a phone. Move closer or further from the window to make the shadow softer or harder. You have just used a National-Artist-level technique for free.\n\nThat is the whole game: name the technique, understand why it works, plan how you will use it."}, {"type": "do", "title": "Guided practice: plan one shot at home", "minutes": 30, "body": "You will not film for a grade here, just plan.\n\n1. Pick one technique from the reading (natural light, real location, the held face, sound/silence, or the long take).\n2. Describe, in 4 to 5 sentences, one shot you could film in your own home or barangay using it: where the camera goes, where the light comes from, what we see.\n3. Say what feeling you want that shot to create.\n\nKeep this plan. It feeds straight into your activity.\n\nWrite up your practice in the box below and submit it. It is auto-graded out of 20 on completion: 10 points for doing it, 10 for enough detail."}, {"type": "reflect", "title": "Reflection before your activity", "minutes": 10, "body": "- Which technique feels most possible for you to try with just a phone?\n- What is one thing a small budget can do BETTER than a big one?\n- Whose work (a Filipino filmmaker, or anyone) would you most like to study next, and why?"}]'::jsonb where activity_id = 'G9-A1.3';
update public.activities set sections = '[{"type": "read", "title": "Warm up: ''I liked it'' is not a critique", "minutes": 10, "body": "Everyone can say ''I liked it'' or ''it was boring.'' A critique is different: it is an argument. It makes a clear claim about how a film was made and whether it works, and it backs that claim with what you actually saw on screen. This task is where you learn to argue like that."}, {"type": "read", "title": "The anatomy of a critique", "minutes": 28, "body": "A film critique has a shape you can rely on.\n\nTHE VERDICT (your claim). One clear sentence: does the film work, and why, in craft terms? Not ''it was good'' but ''the film earns its scares through sound and patience, even when its story is thin.'' A reader should know your position immediately.\n\nTHE EVIDENCE (your proof). At least three specific craft choices you noticed: a shot, a cut, a use of light or music, a performance beat. For each, name the choice and the effect. Vague praise is not evidence. ''The lighting was nice'' proves nothing. ''The single overhead light turned the kitchen into a cage'' proves something.\n\nTHE STRUCTURE. Open with your verdict. Spend the middle proving it, one craft choice per paragraph. Close by returning to the verdict, now earned.\n\nHONEST TONE. A critique can admire and object at the same time. The best ones do both. You are not a hater or a fan, you are a judge.\n\nAND THE AGENT. When you use a free AI agent as a sparring partner, it only attacks your weakest argument so you can make it stronger. It never writes the critique. The argument stays yours, because arguing is the exact skill this task builds."}, {"type": "read", "title": "Worked example: a model paragraph", "minutes": 20, "body": "Here is one body paragraph doing its job. Read how the claim, evidence, and effect lock together.\n\n''The film''s fear lives in its sound, not its monster. For most of the second act we never see the creature; we only hear it, a low wet breathing that the sound mix pushes just under the music. Because the threat stays off screen, our own imagination builds something worse than any costume could. The one time the film shows the creature in full, the tension actually drops. That single choice, to hide and only hint, is why the film works.''\n\nNotice: a claim (fear lives in sound), specific evidence (off-screen breathing under the music), and the effect (imagination does the work), then an honest observation that showing the monster weakens it. That is a critique in miniature."}, {"type": "do", "title": "Guided practice: outline before you write", "minutes": 30, "body": "Do this before your full activity. Choose the film you will critique, then write only an outline:\n\n1. Your VERDICT in one sentence.\n2. Three craft choices you will use as evidence (one line each: the choice, and the effect).\n3. One honest weakness you will admit.\n\nA critique with a strong outline almost writes itself. Keep this; it becomes the skeleton of your submission.\n\nWrite up your practice in the box below and submit it. It is auto-graded out of 20 on completion: 10 points for doing it, 10 for enough detail."}, {"type": "reflect", "title": "Reflection before your activity", "minutes": 10, "body": "- Is your verdict something a reasonable person could disagree with? (A real claim can be argued.)\n- Which of your three pieces of evidence is strongest? Which is weakest?\n- When the AI agent attacks your weakest point, what is your plan: defend it better, or cut it?"}]'::jsonb where activity_id = 'G9-A1.4';
update public.activities set sections = '[{"type": "read", "title": "Warm up: the story you cannot forget", "minutes": 10, "body": "Bring to mind one story you will never forget, from any film, book, or folk tale. It stuck because it had a shape: it pulled you in, raised the stakes, and paid off. That shape is structure, and today you learn to see its spine."}, {"type": "read", "title": "The three-act spine", "minutes": 28, "body": "Almost every story that works rests on the same spine: a beginning that hooks you, a middle that raises the stakes, and an end that pays off. Screenwriters call these the three acts.\n\nACT ONE: SETUP. We meet the character and their ordinary world, then something breaks the routine, the inciting incident, and the story truly begins. The hook lives here: the question that makes us need to know what happens.\n\nACT TWO: CONFRONTATION. The character chases what they want and keeps hitting walls. Stakes rise. Around the middle comes a midpoint, a twist or a point of no return that changes the direction and raises the pressure. This act is the longest and where most weak stories sag.\n\nACT THREE: RESOLUTION. Everything builds to a climax, the biggest confrontation, then a resolution that answers the hook from Act One. A good payoff feels surprising yet, looking back, inevitable.\n\nHOOK AND PAYOFF are a pair. Whatever question you raise at the start, you must answer at the end. When a story wanders and loses you, it is almost always because the spine is missing: no clear hook, flat stakes, or a payoff that ignores the beginning."}, {"type": "read", "title": "Worked example: mapping a familiar tale", "minutes": 20, "body": "A model using the shape of a simple tale, so you can copy the method.\n\nSETUP: a poor young fisher lives an ordinary life by the sea (ordinary world). One day the net pulls up a talking fish that offers one wish (inciting incident). HOOK: what will they wish for, and what will it cost?\n\nCONFRONTATION: the fisher wishes for wealth, gets it, and wants more. Each new wish brings a new problem. MIDPOINT: the wishes start taking more than they give, and the fisher cannot stop.\n\nRESOLUTION: the final wish costs the fisher the one thing that mattered. CLIMAX and payoff: the sea takes everything back, answering the opening question, they wanted more than they needed, and lost what they had.\n\nNotice the method: name the three acts, find the inciting incident, the midpoint, and the way the ending answers the hook. That is reading structure."}, {"type": "do", "title": "Guided practice: break a story into three acts", "minutes": 30, "body": "Pick any story you know well, a film or a folk tale.\n\n1. Write its SETUP in one or two sentences, and name the inciting incident.\n2. Write the CONFRONTATION: what does the character want, what blocks them, and what is the midpoint twist?\n3. Write the RESOLUTION: the climax and how it pays off the hook.\n\nThis is the exact move your activity asks for, done once as practice.\n\nWrite up your practice in the box below and submit it. It is auto-graded out of 20 on completion: 10 points for doing it, 10 for enough detail."}, {"type": "reflect", "title": "Reflection before your activity", "minutes": 10, "body": "- In your chosen story, what is the single question the hook plants in your mind?\n- Does the ending answer that exact question? If not, the spine has a crack, where?\n- Which act do you find hardest to build in your own ideas: the setup, the middle, or the payoff?"}]'::jsonb where activity_id = 'G10-A1.1';
update public.activities set sections = '[{"type": "read", "title": "Warm up: the character you rooted for", "minutes": 10, "body": "Think of a character you desperately wanted to succeed. Why did you care? Almost always it is because they wanted something badly and something stood in their way. That engine, want plus obstacle, is what today is about."}, {"type": "read", "title": "Want, obstacle, and stakes", "minutes": 26, "body": "A story moves because someone wants something and cannot easily get it. Remove the want and the story stops.\n\nTHE WANT must be specific. ''To be happy'' is not a want; it is a fog. ''To win the barangay basketball trophy her late father never won'' is a want, because we can see it, and we can see her fail or succeed at it.\n\nEXTERNAL vs INTERNAL. The external want is the visible goal (win the trophy, get the role, reach home). The internal want is the deeper need (to feel worthy, to be forgiven, to belong). The strongest characters chase both, and the two often pull against each other.\n\nTHE OBSTACLE is what stands in the way: another person, a rule, the world, or the character''s own fear. Without an obstacle the want is granted instantly and there is no story.\n\nSTAKES answer ''so what?'' They are what the character loses if they fail. High, personal stakes are why we lean forward.\n\nFOUND STORIES. Your strongest characters often start from real life, a real person or moment you reshape into fiction. You keep the truth of the feeling and change the facts.\n\nGive a character a clear want and a real obstacle and your story almost writes itself: every scene becomes them trying to get it and hitting a wall."}, {"type": "read", "title": "Worked example: building a wanting character", "minutes": 20, "body": "A model. Watch a flat idea become a character.\n\nFLAT: ''A boy who likes to draw.'' No want, no obstacle, nothing to care about.\n\nADD A SPECIFIC WANT: ''A boy who wants to win the regional comics contest so his name is printed in the paper his lola reads.''\n\nADD AN OBSTACLE: ''But he has to share the family''s one phone, which his sister needs for online class, so he can only draw at midnight.''\n\nADD INTERNAL STAKES: ''He believes that if his lola sees his name in print, she will finally believe art is not a waste of time.''\n\nNow every scene has fuel: stolen midnight hours, the sister''s deadline, the fear of not being taken seriously. Same boy, but now we care, because the want is specific, the obstacle is real, and the stakes are personal."}, {"type": "do", "title": "Guided practice: the character sketch", "minutes": 30, "body": "Invent one character in a short sketch (this is practice for your activity):\n\n1. Name their specific external want (something we could see them win or lose).\n2. Name one real obstacle in the way.\n3. Name the internal stakes: why it matters to them personally.\n4. Base any part of it on a real person or moment you reshape.\n\nKeep it. It becomes the seed of your submission.\n\nWrite up your practice in the box below and submit it. It is auto-graded out of 20 on completion: 10 points for doing it, 10 for enough detail."}, {"type": "reflect", "title": "Reflection before your activity", "minutes": 10, "body": "- Is your character''s want specific enough that we could watch them fail at it?\n- Does the obstacle come from outside, from inside the character, or both?\n- What real feeling from your own life did you reshape into this character?"}]'::jsonb where activity_id = 'G10-A1.2';
update public.activities set sections = '[{"type": "read", "title": "Warm up: what makes your voice yours", "minutes": 10, "body": "Anyone can now generate a script with one click. That is exactly why your own voice is worth more than ever, not less. Today you decide what kind of writer you will be, and you set your own honest rule for using an AI agent."}, {"type": "read", "title": "Voice, plagiarism, and honest AI use", "minutes": 28, "body": "YOUR VOICE is the way only you see and say things: the stories only you could tell, the rhythm of your sentences, the details you notice. It is your value as a writer, and it is the one thing a machine cannot give away for free.\n\nPLAGIARISM is passing off someone else''s work as your own. It comes in forms worth naming. Copying is the obvious one. PATCHWRITING is sneakier: taking someone''s sentences and swapping a few words so it ''looks'' original. AI PLAGIARISM is letting an agent write the work and submitting it as yours. All three throw away the one thing that makes you hireable, a voice that is provably yours.\n\nHONEST AI USE keeps the agent as a tool that serves your voice, never as the author. Good uses: ask it to challenge your weakest argument, to point out where your dialogue sounds fake, to quiz you, to explain a concept. Bad uses: ask it to write the scene, then hand that in.\n\nA SIMPLE TEST: after the agent helps, is the work still unmistakably yours? Could you defend every line as your own thinking? If yes, you used it honestly. If the machine did the thinking, you robbed yourself of the skill this whole term is building.\n\nCULTURAL RESPECT matters too. Drawing from a culture that is not yours without care or credit is its own kind of taking. Write from what you know, and when you borrow, honor the source."}, {"type": "read", "title": "Worked example: two ways to use an agent", "minutes": 20, "body": "A model showing the line between honest and dishonest use, on the same task: writing a short scene.\n\nVOICE-STEALING: The student types ''write me a two-page scene about a fisherman and his son'' and submits what comes back. The words are fluent, but none of them are the student''s. There is nothing to defend, nothing learned, and nothing only this student could have made.\n\nVOICE-SERVING: The student writes the scene themselves, from a real memory of their own lolo. Then they paste it to the agent and ask, ''Which line of dialogue sounds least like a real person?'' The agent flags one stiff line. The student rewrites it in their own words. The scene is still theirs, only sharper.\n\nSame tool, opposite outcomes. The difference is who does the thinking."}, {"type": "do", "title": "Guided practice: draft your AI rule", "minutes": 30, "body": "Write your own honest rule for using an AI agent in your screenwriting this term. Make it specific enough to follow. Answer these in your rule:\n\n1. What WILL you let an agent do for you? (e.g., challenge, quiz, explain)\n2. What will you NEVER let it do?\n3. How will you make sure the final work is still provably your voice?\n\nThis rule is the heart of your activity, and you will follow it for the rest of the term.\n\nWrite up your practice in the box below and submit it. It is auto-graded out of 20 on completion: 10 points for doing it, 10 for enough detail."}, {"type": "reflect", "title": "Reflection before your activity", "minutes": 10, "body": "- Describe your writing voice in one honest sentence. What do only you notice?\n- Have you ever been tempted to patchwrite or let a machine do the work? What did it cost, or nearly cost?\n- Read your AI rule aloud. Could you follow it even on a night you are tired and behind?"}]'::jsonb where activity_id = 'G10-A1.3';
update public.activities set sections = '[{"type": "read", "title": "Warm up: the uniform that gets you read", "minutes": 10, "body": "A brilliant story in the wrong format gets thrown out unread in the real world. Format is the uniform of a professional writer: follow it and a reader takes you seriously before they read a single line. The good news is a free tool puts the uniform on for you."}, {"type": "read", "title": "How a screenplay page is built", "minutes": 26, "body": "Screenplay format is a shared standard so anyone can read your pages instantly. Learn these five elements.\n\nSCENE HEADING (slugline). All caps, tells us three things: interior or exterior, the place, and the time. Example: INT. CLASSROOM - DAY. It orients the reader before the scene starts.\n\nACTION LINES. Written in the present tense, describing only what we can see and hear. Not thoughts, not backstory. ''Maria drops her bag and freezes.'' Keep them lean.\n\nCHARACTER NAME. In capitals and centered above the character''s dialogue, so we know who speaks.\n\nDIALOGUE. Sits under the character name, what they actually say.\n\nPARENTHETICAL. A short cue in brackets under the name for how a line is said, used sparingly. (whispering)\n\nA free tool like WriterDuet, Celtx, or even a screenplay template handles the margins, the capitals, and the centering automatically, so you focus on the story while the tool wears the uniform for you.\n\nWhy it matters: correct format signals you are serious, and it makes your pages readable at a glance. Wrong format signals the opposite, and busy readers stop."}, {"type": "read", "title": "Worked example: a correctly formatted scene", "minutes": 20, "body": "A model of the format. Read how each element sits.\n\nINT. SARI-SARI STORE - NIGHT\n\nRain hammers the tin roof. ALDO (16), soaked, counts coins on the counter.\n\nALDO\n(quietly)\nTwo more. I just need two more.\n\nThe SHOPKEEPER slides a candle across the counter, then pushes the coins back.\n\nSHOPKEEPER\nPay me when the lights come back.\n\nNotice: the heading tells us where and when in caps; the action is present tense and only shows what we see and hear; names are centered and capitalized; a parenthetical gives one small cue. That is the whole uniform. Now the reader trusts you."}, {"type": "do", "title": "Guided practice: format a tiny scene", "minutes": 30, "body": "Before your activity, format a very short scene by hand or in a free tool:\n\n1. Write one scene heading (INT. or EXT., a place, a time).\n2. Write two action lines in the present tense.\n3. Write one character name (capitalized, centered) with two lines of dialogue.\n\nDo not worry about a great story here, worry about clean, correct format. This is the exact skill your submission is graded on.\n\nWrite up your practice in the box below and submit it. It is auto-graded out of 20 on completion: 10 points for doing it, 10 for enough detail."}, {"type": "reflect", "title": "Reflection before your activity", "minutes": 10, "body": "- Which element is easiest to get wrong: the heading, the action tense, or the dialogue layout?\n- Which free tool will you use, and have you opened it yet?\n- Why do you think professionals are so strict about format?"}]'::jsonb where activity_id = 'G10-A1.4';
update public.activities set sections = '[{"type": "read", "title": "Warm up: a piece you can show the world", "minutes": 10, "body": "This is your output for the term. A short, tight, well-formatted screenplay that you wrote yourself is a real portfolio piece, something you could send to a workshop, a contest, or a school. Most people your age have never finished one. You are about to."}, {"type": "read", "title": "Bringing it all together", "minutes": 26, "body": "This task pulls in everything you have learned. A short screenplay that works stands on four legs.\n\nSTRUCTURE. Even in two to four pages, give it a spine: a hook that opens a question, rising stakes in the middle, and a payoff that answers the hook. Short does not mean shapeless.\n\nCHARACTER. Someone wants something specific and hits a real obstacle. In a short script you have no room for a character who wants nothing.\n\nFORMAT. Correct scene headings, present-tense action, centered names, clean dialogue. The uniform you learned last task.\n\nVOICE. This is yours. Follow the honest AI rule you wrote in Task 3.\n\nAND ONE MORE THING, PERFORMABLE DIALOGUE. Dialogue is not how people write, it is how people talk. The test is simple: read it aloud. If it sounds stiff or speech-like, it fails. If it sounds like a real person in a real moment, it works. This is the one thing you will ask a free AI agent to test, and only this: does the dialogue sound performable when read aloud? You keep the notes that help and reject the rest. You decide. The screenplay stays yours.\n\nFINALLY, REVISION. First drafts are where you find the story; revision is where the writing actually gets good. Outline, draft, test, revise. Submit all three so your growth is visible."}, {"type": "read", "title": "Worked example: dialogue that reads aloud", "minutes": 20, "body": "A model of the performable-dialogue test on two versions of the same line.\n\nSTIFF (fails the read-aloud test):\nBEN\nI am very angry with you because you did not tell me that our mother was sick and now I feel betrayed.\n\nNo one talks like that. It is information, not speech.\n\nPERFORMABLE (passes):\nBEN\nYou knew. You knew about Nanay and you let me find out from a neighbor.\n(beat)\nI''m not even angry. That''s the problem.\n\nSame situation, but now it sounds like a real person: shorter, sharper, with something left unsaid. That is what the read-aloud test catches, and it is the only thing you will ask the agent to check."}, {"type": "do", "title": "Guided practice: outline your screenplay", "minutes": 30, "body": "Before you draft, outline (this is the first thing you submit):\n\n1. Your HOOK: the question the opening plants.\n2. Your CHARACTER''s specific want and the obstacle.\n3. The MIDDLE: how the stakes rise.\n4. Your PAYOFF: how the ending answers the hook.\n5. One line of dialogue you already know a character will say.\n\nA screenplay built on a clear outline is far easier to write and revise.\n\nWrite up your practice in the box below and submit it. It is auto-graded out of 20 on completion: 10 points for doing it, 10 for enough detail."}, {"type": "reflect", "title": "Reflection before your activity", "minutes": 10, "body": "- Does your two-to-four-page story have a real hook and a real payoff, or does it just stop?\n- Read one line of your planned dialogue aloud now. Does it sound like a person?\n- What will you ask the AI agent to test, and what will you refuse to let it do?"}]'::jsonb where activity_id = 'G10-A1.5';

select 'practice grading ready' as status;
